"""Explicit corrections checked against descriptions; no blanket text conversion."""
def dice(count, size, damage_type=None, bonus=0):
    return {**({'type': damage_type} if damage_type else {}), 'count': count, 'dice_id': 'd'+str(size), **({'bonus': bonus} if bonus else {})}
def roll(label, count, size, damage_type=None, **kw):
    return {'label': label, 'kind': 'damage' if damage_type else 'effect', 'dices': [dice(count, size, damage_type)], 'scaling': 'none', **kw}

def patch(id, data):
    note = None
    if id in [1056, 987, 1315]: data['time'] = {'kind': 'action'}
    if id in [1353, 1192]: data['concentration'] = True
    if id == 1057: data['concentration'] = False
    if id == 894: data['duration'] = 'Концентрация, вплоть до 24 часов'
    if id == 1120:
        data['damage']['add_mod'] = True
        note = 'Атака и 6к8 + модификатор заклинательной характеристики поддержаны. Обезглавливание при остатке ≤50 хитов, исключения и смерть разрешаются мастером.'
    if id in [1205, 1100]: data['damage']['range_attack'] = True
    if id == 1205:
        note = 'Доступны атака и урон 6к10 по каждой из максимум пяти целей. Отдельные попадания и распределение бросков выбираются вручную; телепортация не требует карты сайта.'
    if id == 1100: data['damage']['save_condition'] = 'В конце хода поражённая цель повторяет спасбросок Телосложения с помехой; успех оканчивает эффект.'
    if id in [584, 890, 604, 1167, 825, 1283, 1368, 1084]:
        data['damage']['save_manual'] = True
        note = 'Урон применяется независимо от спасброска. Спасбросок объявляется отдельно для дополнительного эффекта или его окончания; условия и повторные срабатывания требуют контроля участников.'
    if id in [599, 706, 1090]:
        index = 0 if id == 1090 else 1
        data['damage']['save_manual'] = True
        conditions = {599: 'Взрыв независимо от попадания: цель и существа в 5 футах от осколка.',
                      706: 'Взрыв в начале следующего хода заклинателя: существа в 10 футах от зерна.',
                      1090: 'При появлении сферы или окончании хода внутри неё.'}
        data['rolls'][index].update(save_ability='str' if id == 1090 else 'dex', save_effect='half' if id == 706 else 'negate', save_condition=conditions[id])
        note = 'Попадание и урон области разделены; спасбросок привязан только к броску урона области. Выбор момента повторного срабатывания и контекстных преимуществ — вручную.'
    if id == 1036:
        data['damage'].update(dices=[dice(4, 10, 10)], scaling='none')
        data['rolls'] = [roll('По растениям — вместо обычного урона', 6, 10, 10, save_ability='con', save_effect='half', save_condition='Только растения и растительные существа.')]
        note = 'Доступны 4к10 обычным целям и отдельный вариант 6к10 растениям, спасбросок Телосложения и половина урона при успехе. Тип цели выбирает мастер.'
    if id == 492:
        data['damage'] = {'range_attack': True, 'dices': [dice(1, 10, 13)], 'scaling': 'cantrip', 'instances': 1, 'addon_instances': 1}
        note = 'Атака и 1к10 холодом за попадание поддержаны; с уровнем растёт число атак, а не урон одной. Действие с последовательностью атак и поддержание созданного оружия пока вручную.'
    conditional = {
        977: ([roll('Частичное разрушение камня', 6, 6, 3), {'label': 'Полное разрушение камня', 'kind': 'damage', 'dices': [{'bonus': 50, 'type': 3}], 'scaling': 'none'}], 'Отдельные 6к6 или 50 дробящего урона доступны. Выбор разрушения, падение ничком и помеха слуху — вручную.'),
        846: ([roll('Выталкивание из тесного пространства', 4, 6, 12), roll('Дополнительно за каждые 10 футов сверх 50', 1, 6, 12)], 'Формулы выталкивания доступны отдельно. Преимущество и иммунитеты зависят от освещения; безусловно на лист не накладываются. Дополнительный урон за расстояние повторяют вручную.'),
        981: ([roll('Выталкивание: за каждые 5 футов', 1, 10, 12)], 'Условный урон выталкивания доступен на каждый участок пути. Дистанцию определяет мастер; бросок за каждый участок повторяется вручную.'),
        1198: ([roll('При получении другого урона', 1, 4, 10)], 'Дополнительный урон 1к4 доступен отдельно. Расход пяти Костей Хитов, снижение максимума, снятие защит, смена типа и особая смерть требуют отдельной механики.'),
        1336: ([roll('При получении степени истощения от дождя', 2, 10, 10)], 'Урон 2к10 доступен отдельно. Расход восьми Костей Хитов, истощение, уменьшение максимума и автоматические провалы пока вручную.'),
        903: ([roll('Крутое течение: смытые существа', 3, 8, 3)], 'Доступен урон 3к8 при выборе крутого течения. Первоначальный спасбросок Силы, последующий спасбросок Телосложения для подводного течения, состояния и их снятие требуют отдельного разрешения.'),
        1298: ([roll('Попадание стены', 4, 6, 2)], 'Урон отдельного попадания стены доступен. Нужен отдельный лист созданной стены, её атаки, хиты и команды.'),
        461: ([roll('Уменьшение следующего урона', 1, 4)], 'Бросок уменьшения урона доступен. Применение к следующему попаданию и завершение концентрации после него — вручную.'),
        894: ([roll('Обрушение при результате 5–6', 1, 6)], 'Бросок обрушения доступен; строительство карточного дома и его разрушение разрешает мастер.'),
        1404: ([roll('Дополнительных ходов', 1, 4, dices=[dice(1, 4, bonus=1)])], 'Бросок 1к4+1 дополнительных ходов доступен. Временная очередь ходов и досрочное окончание при воздействии на других — вручную.'),
        1061: ([roll('Занятое место назначения', 4, 6, 12)], 'Условные 4к6 силовым полем при занятом месте назначения доступны. Допустимость телепортации и её участников определяет мастер.'),
        784: ([roll('Начало хода в горящей паутине', 2, 4, 5)], 'Урон горящей паутины и спасбросок доступны отдельно. Опутывание, освобождение проверкой Силы и снятие состояния пока вручную.'),
        1093: ([roll('Цена сотворения: урон себе', 1, 4, 1)], 'Добавлен отдельный бросок урона заклинателю. Создание теневого духа, его отдельный лист и действия требуют отдельной механики.'),
    }
    if id in conditional:
        rows, note = conditional[id]
        assert not data.get('rolls'), f'Existing conditional rolls {id}'
        data['rolls'] = rows
    if id == 1248: data['application_targets'] = {'count': 12}
    if id in [619, 1382]: data['application_targets'] = {**data.get('application_targets', {}), 'self_only': True}
    if id in [975, 1342]: data['application_targets'] = {**data.get('application_targets', {}), 'count': 50}
    return note
